#!/usr/bin/env bash
#
# Hubcast project restorer.
#
# Recreates the full source tree with correct directory structure. GitHub's
# web uploader flattens folders, which is why this exists.
#
# Usage, from inside your cloned repo:
#
#     bash restore-hubcast.sh
#     git add -A && git commit -m "Restore project structure" && git push
#
# Safe to run in a repo that already has the flattened files: it removes the
# stray root-level copies before writing the real tree.

set -euo pipefail

if [ ! -d .git ]; then
  echo "Run this from inside the cloned repository (no .git found here)." >&2
  exit 1
fi

# Remove flattened duplicates left by the web uploader. These are the same
# files, just in the wrong place, so deleting them loses nothing.
for stray in MainActivity.kt NostrSignerPlugin.kt AndroidManifest.queries.xml \
             android.yml nip55.js signer.svelte.js nostr.js kinds.js \
             wire-native.mjs app.css app.html sw.js manifest.webmanifest \
             SignIn.svelte QrCode.svelte TallyLamp.svelte LinkRow.svelte; do
  if [ -f "$stray" ]; then
    rm -f "$stray"
    echo "removed stray ./$stray"
  fi
done

echo "extracting project tree..."
base64 -d <<'PAYLOAD_EOF' | tar xzf -
